WITH cleaned AS (SELECT *, ROUND(duration_sec * 1.1, 2) AS duration_sec_adjusted, CASE WHEN duration_sec >= 513 THEN 'High' WHEN duration_sec >= 132 THEN 'Medium' ELSE 'Low' END AS duration_sec_tier FROM web_events WHERE event_time >= TO_TIMESTAMP('2023-08-17 22:00:00') AND event_time >= '2023-04-01'), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM cleaned), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT event_type, COUNT(DISTINCT page) AS distinct_pages, COUNT(DISTINCT page) AS distinct_pages_2, SUM(CASE WHEN page = '/home' THEN burst_id ELSE 0 END) AS home_burst_id, MIN(event_time) AS started_at, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min FROM islands GROUP BY event_type HAVING (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 > 0
